import os
import pandas as pd
from pathlib import Path

# First, let's check what policy documents are available in the current directory
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() and file.endswith(('.txt', '.pdf', '.doc', '.docx', '.md')):
        policy_files.append(file)

print("Found policy files:", policy_files)

# If no policy files found, let's search more broadly
if not policy_files:
    print("Searching for any text files that might contain policy information...")
    for file in os.listdir('.'):
        if file.endswith('.txt'):
            policy_files.append(file)

print("\nAvailable policy documents:", policy_files)
